"""Stock availability for a single product in the web shop."""

HOLD_S = 300  # Seconds an unpaid reservation holds its units.


def available(stock, reservations, now_s, hold_s=HOLD_S):
    """Return how many units can still be sold.

    stock        -- units on the shelf (int >= 0)
    reservations -- iterable of dicts with keys 'qty', 'created_s', 'paid'
    now_s        -- current time in seconds, same epoch/units as created_s
    hold_s       -- how long an unpaid reservation holds its units

    A reservation holds its units if it is paid (paid ones never expire),
    or if it is unpaid and younger than hold_s seconds. An unpaid
    reservation stops holding at exactly hold_s seconds of age.
    A reservation with created_s in the future counts as active.

    Assumption: paid reservations are NOT already subtracted from `stock`.
    If your checkout decrements stock on payment, pass only unpaid
    reservations, or paid units will be counted twice.

    The result is never below 0, even if reservations exceed stock.
    The function is pure: it reads no clock and does not modify its inputs.
    """
    if isinstance(stock, bool) or not isinstance(stock, int):
        raise TypeError("stock must be an int")
    if stock < 0:
        raise ValueError("stock must not be negative")
    if hold_s < 0:
        raise ValueError("hold_s must not be negative")

    held = 0
    for i, r in enumerate(reservations):
        try:
            qty = r["qty"]
            created_s = r["created_s"]
            paid = r["paid"]
        except (KeyError, TypeError):
            raise ValueError(
                f"reservation {i} must be a dict with 'qty', 'created_s' and 'paid'"
            ) from None
        if isinstance(qty, bool) or not isinstance(qty, int):
            raise TypeError(f"reservation {i}: qty must be an int")
        if qty < 0:
            raise ValueError(f"reservation {i}: qty must not be negative")

        if paid or now_s - created_s < hold_s:
            held += qty

    return max(0, stock - held)


if __name__ == "__main__":
    import unittest

    def res(qty, created_s, paid=False):
        return {"qty": qty, "created_s": created_s, "paid": paid}

    class AvailableTests(unittest.TestCase):
        def test_no_reservations(self):
            self.assertEqual(available(10, [], 1000), 10)

        def test_zero_stock(self):
            self.assertEqual(available(0, [], 1000), 0)
            self.assertEqual(available(0, [res(2, 1000)], 1000), 0)

        def test_paid_never_expires(self):
            self.assertEqual(available(10, [res(3, 0, paid=True)], 10**9), 7)

        def test_unpaid_expiry_boundary(self):
            r = [res(4, 1000)]
            self.assertEqual(available(10, r, 1299), 6)   # just before
            self.assertEqual(available(10, r, 1300), 10)  # exactly at 300 s
            self.assertEqual(available(10, r, 1301), 10)  # just after

        def test_future_created_is_active(self):
            self.assertEqual(available(10, [res(2, 2000)], 1000), 8)

        def test_mixed(self):
            r = [res(1, 0, paid=True), res(2, 900), res(5, 100)]
            self.assertEqual(available(10, r, 1000), 7)

        def test_oversold_clamps_to_zero(self):
            r = [res(6, 1000), res(6, 1000, paid=True)]
            self.assertEqual(available(10, r, 1000), 0)

        def test_inputs_not_modified(self):
            r = [res(2, 1000)]
            snapshot = [dict(x) for x in r]
            available(10, r, 1000)
            self.assertEqual(r, snapshot)

        def test_invalid_inputs(self):
            with self.assertRaises(ValueError):
                available(-1, [], 0)
            with self.assertRaises(ValueError):
                available(10, [res(-1, 0)], 0)
            with self.assertRaises(ValueError):
                available(10, [{"qty": 1}], 0)
            with self.assertRaises(TypeError):
                available(10, [res(1.5, 0)], 0)

    unittest.main()
